#!/usr/bin/env python3
"""
Comprehensive translation fix — Part 2
Adds translations for all dashboard.settings keys and other common sections.
"""
import json, os

MESSAGES_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'apps', 'web', 'messages')

def load_json(lang):
    with open(os.path.join(MESSAGES_DIR, f'{lang}.json'), 'r', encoding='utf-8') as f:
        return json.load(f)

def save_json(lang, data):
    with open(os.path.join(MESSAGES_DIR, f'{lang}.json'), 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')

def set_value(obj, key_path, value):
    keys = key_path.split('.')
    cur = obj
    for k in keys[:-1]:
        if k not in cur:
            cur[k] = {}
        cur = cur[k]
    cur[keys[-1]] = value

def has_key(obj, key_path):
    try:
        keys = key_path.split('.')
        cur = obj
        for k in keys:
            cur = cur[k]
        return True
    except KeyError:
        return False

def get_value(obj, key_path):
    keys = key_path.split('.')
    cur = obj
    for k in keys:
        cur = cur[k]
    return cur

