# Apply all translations
def apply_translations():
    en = load_json('en')
    lang_codes = sorted([f.replace('.json', '') for f in os.listdir(MESSAGES_DIR) if f.endswith('.json') and f != 'en.json'])
    
    stats = {}
    for lang in lang_codes:
        data = load_json(lang)
        changes = 0
        
        for key_path, translations in KEY_TRANSLATIONS.items():
            if lang in translations:
                # Only set if currently same as English or missing
                try:
                    current = get_value(data, key_path)
                    en_val = get_value(en, key_path)
                    if current == en_val:
                        set_value(data, key_path, translations[lang])
                        changes += 1
                except (KeyError, TypeError):
                    set_value(data, key_path, translations[lang])
                    changes += 1
        
        save_json(lang, data)
        stats[lang] = changes
    
    print("Part 2 translation results:")
    for lang, changes in sorted(stats.items(), key=lambda x: -x[1]):
        if changes > 0:
            print(f"  {lang}: {changes} fixes")

if __name__ == '__main__':
    apply_translations()
